<script lang="ts">
	import { onMount } from 'svelte';
	import type { Session } from '@supabase/supabase-js';
	import { updateScene, type Scene } from '$lib/services/sceneApi';
	import { supabase } from '$lib/services/supabase';
	let { scene, session, onclose, onsaved }: { scene: Scene; session: Session; onclose: () => void; onsaved: (scene: Scene) => void } = $props();
	let draft = $state<Scene>({} as Scene), saving = $state(false), message = $state('');
	let audioFiles = $state<{ path: string; name: string }[]>([]);
	$effect(() => { draft = { ...scene }; });
	onMount(async () => { if (!supabase) return; const folder = `campaigns/${scene.campaignId}/media`; const { data, error } = await supabase.storage.from('campaign-assets').list(folder, { limit: 100 }); if (error) { message = error.message; return; } audioFiles = (data ?? []).filter((file) => file.metadata?.mimetype?.startsWith('audio/')).map((file) => ({ path: `${folder}/${file.name}`, name: file.name.replace(/^[a-f0-9-]+-/, '') })); });
	async function save() { saving = true; message = ''; try { const result = await updateScene(session, draft); onsaved(result); onclose(); } catch (error) { message = error instanceof Error ? error.message : 'Não foi possível salvar a cena.'; } finally { saving = false; } }
</script>
<div class="backdrop" role="presentation" onclick={(event) => event.currentTarget === event.target && onclose()}><section><header><div><p>CENA</p><h2>Configurações</h2></div><button onclick={onclose}>×</button></header><form onsubmit={(event) => { event.preventDefault(); void save(); }}><label>Nome<input bind:value={draft.name} maxlength="120"/></label><label>Imagem de fundo<input bind:value={draft.backgroundUrl} placeholder="URL pública da imagem"/></label><label>Trilha da cena<select bind:value={draft.ambientAudioPath}><option value="">Sem trilha</option>{#each audioFiles as audio (audio.path)}<option value={audio.path}>{audio.name}</option>{/each}</select></label><label>Volume da trilha<input bind:value={draft.ambientAudioVolume} type="number" min="0" max="100"/></label><label class="toggle"><input type="checkbox" bind:checked={draft.ambientAudioEnabled} disabled={!draft.ambientAudioPath}/> Reproduzir trilha para participantes</label><label>Grid em pixels<input bind:value={draft.gridSize} type="number" min="20" max="200"/></label><label>Visibilidade para jogadores<select bind:value={draft.playerAccess}><option value="hidden">Oculta — ninguém vê</option><option value="available">Disponível — jogadores podem abrir</option><option value="active">Ativa — cena do grupo</option></select></label><label>Névoa de guerra<select bind:value={draft.fogEnabled}><option value={false}>Desativada</option><option value={true}>Ativada</option></select></label><label>Modo de visão<select bind:value={draft.visionMode}><option value="manual">Manual</option><option value="shared">Compartilhada</option><option value="token">Por token</option></select></label><label class="toggle"><input type="checkbox" bind:checked={draft.allowPlayerMovement}/> Jogadores podem mover apenas seus próprios tokens</label><label class="toggle"><input type="checkbox" bind:checked={draft.allowPlayerDoorInteraction}/> Jogadores podem interagir com portas próximas</label><p>Envie áudios na Biblioteca. O navegador pede uma interação de cada participante antes de reproduzir som; depois disso, a faixa e o volume definidos aqui são compartilhados.</p>{#if message}<small>{message}</small>{/if}<footer><button type="button" onclick={onclose}>Cancelar</button><button class="primary" disabled={saving}>{saving ? 'Salvando…' : 'Salvar cena'}</button></footer></form></section></div>
<style>.backdrop{position:fixed;z-index:30;inset:0;display:grid;place-items:center;padding:1rem;background:#080608b8}.backdrop section{width:min(100%,540px);border:1px solid #765d3d;border-radius:12px;overflow:hidden;color:#eee4d6;background:#1b171a}.backdrop header{display:flex;justify-content:space-between;padding:1rem;border-bottom:1px solid #493c39}.backdrop header p{margin:0;color:#d8ad67;font-size:.65rem;letter-spacing:.12em}.backdrop h2{margin:.25rem 0 0;font:600 1.35rem Georgia,serif}.backdrop header button,footer button{border:0;color:#cbb9a7;background:transparent;font:inherit;cursor:pointer}.backdrop header button{font-size:1.4rem}.backdrop form{display:grid;gap:.7rem;padding:1rem}.backdrop label{display:grid;gap:.25rem;color:#b9aa9d;font-size:.7rem}.backdrop input,.backdrop select{border:1px solid #59483b;border-radius:6px;padding:.55rem;color:#eadfce;background:#161216;font:inherit}.backdrop label.toggle{display:flex;align-items:center;gap:.55rem;border:1px solid #59483b;border-radius:6px;padding:.65rem}.backdrop label.toggle input{accent-color:#d8ad67}.backdrop p,.backdrop small{margin:0;color:#a99c91;font-size:.75rem;line-height:1.45}.backdrop footer{display:flex;justify-content:flex-end;gap:.7rem;margin-top:.4rem}.backdrop footer button{border:1px solid #765d3d;border-radius:7px;padding:.5rem .7rem}.backdrop footer .primary{border:0;color:#26190e;background:#e0b86f}</style>
